import schedule2026 from "../../data/normalized/economics/schedule-2026-2027.json" with { type: "json" };

// Generated by compile:policy from policy/schedules/2026-2027.json.
export const DERIVED_SCHEDULE_2026_2027 = schedule2026;

const CROSS_LISTED_CODES = Object.freeze({
  "PHI 234": "ECO 234"
});

export function normalizeScheduleCourseCode(value) {
  const normalized = String(value || "").trim().toUpperCase().replace(/\s+/g, " ");
  return CROSS_LISTED_CODES[normalized] || normalized;
}

export function buildScheduleCourseSets(schedule = DERIVED_SCHEDULE_2026_2027, terms) {
  const termNames = terms || Object.keys(schedule.terms || {});
  return Object.fromEntries(termNames.map(term => [
    term,
    new Set((schedule.terms?.[term] || []).map(row => normalizeScheduleCourseCode(row.course)))
  ]));
}

export function renderScheduleKnowledge(schedule = DERIVED_SCHEDULE_2026_2027) {
  const lines = [
    `Canonical economics schedule for academic year ${schedule.academicYear}.`,
    "Use these offerings exactly for dated 2026/2027 placements.",
    "ECO 234 and PHI 234 are cross-listed codes for the same offering; do not count both separately.",
    ""
  ];

  for (const [term, courses] of Object.entries(schedule.terms || {})) {
    lines.push(`${term}:`);
    for (const course of courses) {
      const details = [course.course, course.section, course.title].filter(Boolean).join(" | ");
      lines.push(`- ${details}`);
    }
    lines.push("");
  }

  return lines.join("\n").trim();
}
